// Playlist: https://www.shadertoy.com/playlist/mfdGWj

// Recreating some illustrations from Eric Lengyel's "Projective Geometric Algebra Illuminated".

// Builds off the 1D case here: https://www.shadertoy.com/view/MXccDl

// The gray plane represents the W=1 projection plane. 

// Given three 4D homogeneous vectors, P, Q, and R, which together span a solid volume (the green parallelogram), 
// when we divide these two points by W, we project these points down to the projection plane,
// ie PProj = P / P.w, QProj = Q / Q.w, and RProj = R / R.w, these three points form a plane (the dark green triangle) in 
// the N-1 dimensional subspace (here, the light gray projection plane).

// In other words, planes in 3D are duals to solids in 4D


// between two vec2's, the wedge product returns area of a parallelogram
float wedge(vec2 a, vec2 b) {
    return (a.x*b.y - a.y*b.x);    
}

// between two vec3's, the wedge product returns a bivector, whose coefficients 
// describe a 2D line in the W=1 projection plane.
//  0 = Ax + By + Cw, where ABC = cross(p,q)
// and whose magnitude describes the area of an oriented parallelogram.
vec3 wedge(vec3 p, vec3 q) {
    // visually appears as a cross product, but 
    // also can be interpreted as coefficients for a line, 
    #if 1
    return cross(p, q);
    #else
    return vec3(
        wedge(p.yz, q.yz),  // A
        wedge(p.zx, q.zx),  // B
        wedge(p.xy, q.xy)   // C
    );
    #endif
}

// between three vec3's, the wedge product returns a trivector, which is a singular scalar value
// that scales a "unit volume" element "e123". Geometrically, p∧q∧r = gw * e123.
// That scalar is the signed paralellepiped volume spanned by p, q, and r, and is sometimes called a "pseudoscalar".
//
// In 3D, the signed area of the triangle where the parallelepiped and the W=1 projection plane meet can be found as
//  area(triangle) = 1/2 (wedge(p,q,r) / length((pw,qw,rw)))
// 
// In 4D, the wedge product between three vectors produces a four-component trivector,
// whose coefficients project down to defining a plane.
//   g = gx*e423 + gy*e431 * gz*412 + gw*e321
//       [coefs give plane's normal] [position]
float wedge(vec3 p, vec3 q, vec3 r) {
    #if 1
    return determinant(mat3(p, q, r));
    #else
    return p.x * wedge(q.yz, r.yz)
         + p.y * wedge(q.zx, r.zx)
         + p.z * wedge(q.xy, r.xy);
    #endif
}

#define OUTLINE_WIDTH .01

#define M2PI 6.28318530718

#if HW_PERFORMANCE==0
#define AA 1
#else
#define AA 2   // make this 2 or 3 for antialiasing
#endif

struct Payload {
    float d; // distance
    vec3 albedo; // albedo
};

const float lineThickness = .002;
const float arrowThickness = .002;
const float arrowCapWidth = .06;
const float arrowCapHeight = .12;

const float xLength = 2.0;
const float yLength = 8./3.;
const float wLength = 2.0;
const float wPlaneHeight = 1.0;

Payload map(in vec3 ro, vec3 rd) {
    Payload res;
    res.d = 1e38f;
    res.albedo = vec3(0.0);

    // Animate the vector moving

    vec3 P = vec3(sin(iTime*.5 + mix(0.0, M2PI, .3)) * .5 + 1., cos(iTime*.5 + mix(0.0, M2PI, .3))* .5 + 1., 1.0) * vec3(yLength * .4, xLength * .6, wPlaneHeight);    
    vec3 Q = vec3(sin(iTime*.5 + mix(0.0, M2PI, .6)) * .5 + 1., cos(iTime*.5 + mix(0.0, M2PI, .6))* .5 + 1., 1.0) * vec3(yLength * .4, xLength * .6, wPlaneHeight);
    vec3 R = vec3(sin(iTime*.5 + mix(0.0, M2PI, .9)) * .5 + 1., cos(iTime*.5 + mix(0.0, M2PI, .9))* .5 + 1., 1.0) * vec3(yLength * .4, xLength * .6, wPlaneHeight);


    // Projecting the 4D trivector down to a 3D subspace
    // (illustrating as a 3D bivector projecting down to a 2D space)
    vec3 PProj = P / P.z;
    vec3 QProj = Q / Q.z;
    vec3 RProj = R / R.z;

    // Outlines of P ^ Q ^ R
    {
        float d = 1e38f;

        d = min(d, sdCapsule( ro, vec3(0.0), P, 0.0 ));
        d = min(d, sdCapsule( ro, vec3(0.0), Q, 0.0 ));
        d = min(d, sdCapsule( ro, vec3(0.0), R, 0.0 )); 

        d = min(d, sdCapsule( ro, P, P+Q, 0.0 ));
        d = min(d, sdCapsule( ro, P, P+R, 0.0 ));

        d = min(d, sdCapsule( ro, Q, Q+P, 0.0 ));
        d = min(d, sdCapsule( ro, Q, Q+R, 0.0 ));

        d = min(d, sdCapsule( ro, R, R+P, 0.0 ));
        d = min(d, sdCapsule( ro, R, R+Q, 0.0 ));


        d = min(d, sdCapsule( ro, P+Q, P+Q+R, 0.0 ));
        d = min(d, sdCapsule( ro, Q+R, P+Q+R, 0.0 ));
        d = min(d, sdCapsule( ro, R+P, P+Q+R, 0.0 )); 


        if (d < res.d) {res.d = d; res.albedo = vec3(0.0, 0.0, 0.0);}
    }

    // Arrow passing through the projection plane

    {      
        vec3 cheat = -rd*.01 + vec3(0.,0.,.01);
        vec3 cen = (PProj + QProj + RProj) / 3.0;


        vec3 cheat1 = .0 * normalize(PProj - cen);
        vec3 cheat2 = .0 * normalize(QProj - cen);
        vec3 cheat3 = .0 * normalize(RProj - cen);


        float d1 = sdSphere(ro - (PProj + -rd*.1), .06);
        if (d1 < res.d) {res.d = d1; res.albedo = emerald;}

        float d2 = sdSphere(ro - (QProj + -rd*.1), .06);
        if (d2 < res.d) {res.d = d2; res.albedo = emerald;}

        float d3 = sdSphere(ro - (RProj + -rd*.1), .06);
        if (d3 < res.d) {res.d = d3; res.albedo = emerald;}

        float dt = udTriangle(ro, PProj + cheat1 + cheat, QProj + cheat2 + cheat, RProj + cheat3 + cheat) - arrowThickness*6.;
        if (dt < res.d) {res.d = dt; res.albedo = emerald;}

        vec3 dir1 = normalize(PProj - cen);
        vec3 dir2 = normalize(QProj - cen);
        vec3 dir3 = normalize(RProj - cen);

        float da = sdCapsule(ro, PProj - rd*.06, QProj - rd*.06, arrowThickness*6.);
        if (da < res.d) {res.d = da; res.albedo = emerald;}

        float db = sdCapsule(ro, QProj - rd*.06, RProj - rd*.06, arrowThickness*6.);
        if (db < res.d) {res.d = db; res.albedo = emerald;}

        float dc = sdCapsule(ro, RProj - rd*.06, PProj - rd*.06, arrowThickness*6.);
        if (dc < res.d) {res.d = dc; res.albedo = emerald;}
    }


    // X axis arrow
    {
        float d = sdArrow(ro, vec3(0.0), vec3(xLength, 0.0, 0.0), arrowThickness, arrowCapWidth, arrowCapHeight);
        if (d < res.d) {res.d = d; res.albedo = vec3(0.0, 0.0, 0.0);}
    }

    // Y axis arrow
    {
        float d = sdArrow(ro, vec3(0.0), vec3(0.0, yLength, 0.0), arrowThickness, arrowCapWidth, arrowCapHeight);
        if (d < res.d) {res.d = d; res.albedo = vec3(0.0, 0.0, 0.0);}
    }

    // W axis arrow
    {
        float d = sdArrow(ro, vec3(0.0), vec3(0.0, 0.0, wLength), arrowThickness, arrowCapWidth, arrowCapHeight);
        if (d < res.d) {res.d = d; res.albedo = vec3(0.0, 0.0, 0.0);}
    }

    // 90 degree marker between X and Y
    {
        float d1 = sdCapsule( ro, vec3(xLength * .1, 0., 0.), vec3(xLength * .1, xLength * .1, 0.), lineThickness );
        float d2 = sdCapsule( ro, vec3(xLength * .1, xLength * .1, 0.), vec3(0., xLength * .1, 0.), lineThickness );        
        float d = min(d1, d2);
        if (d < res.d) {res.d = d; res.albedo = vec3(0.0, 0.0, 0.0);}
    }

    // W=1 plane outline
    {
        vec3 lo = vec3(-1.2, -1.2, wPlaneHeight);
        vec3 hi = vec3(xLength, yLength, wPlaneHeight);

        // Opaque outline
        float d = sdBoxFrame( ro, lo, hi, .0 );
        if (d < res.d) {res.d = d; res.albedo = vec3(0.0, 0.0, 0.0);}
    }

    // 90 degree marker between W and YZ plane
    {
        float d1 = sdCapsule( ro, vec3(0., 0., wPlaneHeight + xLength * .1), vec3(0., xLength * .1, wPlaneHeight + xLength * .1), lineThickness );
        float d2 = sdCapsule( ro, vec3(0., xLength * .1, wPlaneHeight + xLength * .1), vec3(0., xLength * .1, wPlaneHeight), lineThickness );        
        float d = min(d1, d2);
        if (d < res.d) {res.d = d; res.albedo = vec3(0.0, 0.0, 0.0);}
    }

    return res;
}

vec4 over(vec4 a, vec4 b) {
  vec4 result;
  result.a = a.a + b.a * (1.f - a.a);
  if (result.a == 0.f)
    return a;   // avoid NaN
  result.rgb = (a.rgb * a.a + b.rgb * b.a * (1.f - a.a)) / result.a;
  return result;
}

vec3 scene(in vec3 ro,in vec3 rd) {
    vec3 col = vec3(1.0);		// initialize color return value

    vec3 roStart = ro;

    vec3 P = vec3(sin(iTime*.5 + mix(0.0, M2PI, .3)) * .5 + 1., cos(iTime*.5 + mix(0.0, M2PI, .3))* .5 + 1., 1.0) * vec3(yLength * .4, xLength * .6, wPlaneHeight);    
    vec3 Q = vec3(sin(iTime*.5 + mix(0.0, M2PI, .6)) * .5 + 1., cos(iTime*.5 + mix(0.0, M2PI, .6))* .5 + 1., 1.0) * vec3(yLength * .4, xLength * .6, wPlaneHeight);
    vec3 R = vec3(sin(iTime*.5 + mix(0.0, M2PI, .9)) * .5 + 1., cos(iTime*.5 + mix(0.0, M2PI, .9))* .5 + 1., 1.0) * vec3(yLength * .4, xLength * .6, wPlaneHeight);

    vec4 tuvs[8];

    tuvs[0].w = 0.0;
    tuvs[1].w = 1.0;
    tuvs[2].w = 2.0;
    tuvs[3].w = 3.0;
    tuvs[4].w = 4.0;
    tuvs[5].w = 5.0;
    tuvs[6].w = 6.0;
    tuvs[7].w = 7.0;


    // W plane
    {
        vec3 lo = vec3(-1.2, -1.2, wPlaneHeight);
        vec3 hi = vec3(xLength, yLength, wPlaneHeight);
        tuvs[0].xyz = parallelogramIntersect(ro, rd, lo, vec3(hi.x, lo.y, lo.z), vec3(lo.x, hi.y, lo.z) );

    }

    // Faces of the 4D trivector (illustrated as a parallelogram in 3D)
    {
        tuvs[1].xyz = parallelogramIntersect(ro, rd, vec3(0.0), P, Q );
        tuvs[2].xyz = parallelogramIntersect(ro, rd, vec3(0.0), Q, R );
        tuvs[3].xyz = parallelogramIntersect(ro, rd, vec3(0.0), R, P );


        tuvs[4].xyz = parallelogramIntersect(ro, rd, P, P + Q, P + R );
        tuvs[5].xyz = parallelogramIntersect(ro, rd, Q, Q + R, Q + P );
        tuvs[6].xyz = parallelogramIntersect(ro, rd, R, R + P, R + Q );
    }    


    Payload payload;

    float rm = 1e38f; 			// tracker for minimum ray value
    float tmin = 15.0;
    float tmax = 23.0;
    float t = tmin;
    ro = roStart + t * rd;

    float ow = OUTLINE_WIDTH; 		// outline width
    for (int i =0; i<50; i++) {
        payload = map(ro, rd);
        rm = min(payload.d, rm);

        //check if a ray has passed through an outline region
        if (payload.d > rm && rm < ow * 1.5){
            col = vec3(0); //outline
            break;
        }

        if (payload.d < ow * .01) {
            float edge = map(ro, rd).d;
            //color based on suface location
            col = payload.albedo;
            break;
        }

        t += payload.d * .99;
       	ro = roStart + t * rd;//*0.85;
        if (t > tmax) break;
    }

    if (payload.d > rm && rm < ow) {
        col = vec3(0); //outline
    }

    tuvs[7].x = t;

    vec4 bgcol = vec4(col, 1.0);

    // Sort by hit depth
    for (int i = 0; i < 7; ++i) {
        for (int j = 0; j < 7; ++j) {
            if (tuvs[j].x < tuvs[j+1].x) {
                vec4 tmp = tuvs[j];
                tuvs[j] = tuvs[j+1];
                tuvs[j+1] = tmp;
            }
        }
    }

    // Composite the W=1 plane
    vec4 rgba = vec4(1.0, 1.0, 1.0, .0);
    for (int i = 0; i < 8; ++i) {
        if( tuvs[i].x>0.0)
        {
            vec4 geoCol;
            if (tuvs[i].w == 0.0) geoCol = vec4(lightGray, .8);
            else if (tuvs[i].w == 7.0) geoCol = vec4(col, 1.0);
            else geoCol = vec4(green, .7);            
            rgba = over(geoCol, rgba);
        }
    }

    return rgba.rgb;
}

mat3 lookAt(in vec3 eye, in vec3 tar, in float r){
    vec3 cw = normalize(tar - eye);// camera w
    vec3 cp = vec3(sin(r), 0., cos(r));// camera up
    vec3 cu = normalize(cross(cw, cp));// camera u
    vec3 cv = normalize(cross(cu, cw));// camera v
    return mat3(cu, cv, cw);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 tot = vec3(0.0);

    // camera
    float an = .2;//-0.05*iTime -5.0*iMouse.x/iResolution.x;

    float dist = 20.f;
    float fov = 5.f;


    vec3  ro = dist * vec3(cos(3.0*an),sin(3.0*an), .3);
    vec3  ta = vec3(0.0,0.0,2.5/6.0);

    // camera matrix
    vec3 ww = normalize( ta - ro );
    vec3 uu = normalize( cross(ww,vec3(0.0,0.0,1.0) ) );
    vec3 vv = normalize( cross(uu,ww));

    for( int m=0; m<AA; m++ )
    for( int n=0; n<AA; n++ )
    {           
        //create p for ray based on AA settings
        vec3 p = vec3((-iResolution.xy + 2.0*(fragCoord.xy-0.5+(vec2(float(m),float(n))+0.5)/float(AA))) / iResolution.y,2.0);


        //create view ray from vector p
        vec3 rd = lookAt(ro, ta, 0.)*normalize(vec3(p.xy, 1.0/radians(fov)));// ray direction

        //render scene
        vec3 col = scene(ro,rd);

        //vignette
        //col -= 0.2*length(p.xy);

        tot += col;
    }
    tot /= float(AA*AA);
    fragColor = vec4( tot, 1.0 );
}

const vec3 black = vec3(0.)/255.;
const vec3 white = vec3(255.)/255.;
const vec3 lightGray = vec3(205.)/255.;
const vec3 mediumGray = vec3(140.)/255.;
const vec3 darkGray = vec3(94.)/255.;

const vec3 green = vec3(118., 185.,0.)/255.;
const vec3 emerald = vec3(0.,133.,100.)/255.;
const vec3 blue = vec3(0.,113.,197.)/255.;
const vec3 purple = vec3(93.,22.,130.)/255.;
const vec3 yellow = vec3(250.,194.,0.)/255.;
const vec3 garnet = vec3(137.,12.,88.)/255.;

vec3 parallelogramIntersect( in vec3 ro, in vec3 rd, in vec3 v0, in vec3 v1, in vec3 v2 )
{
    vec3 a = v0 - v1;
    vec3 b = v2 - v0;
    vec3 p = v0 - ro;

    vec3 n = cross( a, b );
    vec3 q = cross( rd, p );

    float i = 1.0/dot( rd, n );

    float u = dot( q, a )*i;
    float v = dot( q, b )*i;
    float t = dot( n, p )*i;

    if( u<0.0 || u>1.0 || v<0.0 || v>1.0 ) return vec3(-1.0);

    return vec3( t, u, v );
}

//------------------------------------------------------------------
float dot2( in vec2 v ) { return dot(v,v); }
float dot2( in vec3 v ) { return dot(v,v); }
float ndot( in vec2 a, in vec2 b ) { return a.x*b.x - a.y*b.y; }

float udTriangle( in vec3 p, in vec3 v1, in vec3 v2, in vec3 v3)
{
    vec3 v21 = v2 - v1; vec3 p1 = p - v1;
    vec3 v32 = v3 - v2; vec3 p2 = p - v2;
    vec3 v13 = v1 - v3; vec3 p3 = p - v3;
    vec3 nor = cross( v21, v13 );

    return sqrt( (sign(dot(cross(v21,nor),p1)) + 
                  sign(dot(cross(v32,nor),p2)) + 
                  sign(dot(cross(v13,nor),p3))<2.0) 
                  ?
                  min( min( 
                  dot2(v21*clamp(dot(v21,p1)/dot2(v21),0.0,1.0)-p1), 
                  dot2(v32*clamp(dot(v32,p2)/dot2(v32),0.0,1.0)-p2) ), 
                  dot2(v13*clamp(dot(v13,p3)/dot2(v13),0.0,1.0)-p3) )
                  :
                  dot(nor,p1)*dot(nor,p1)/dot2(nor) );
}

float udQuad( in vec3 v1, in vec3 v2, in vec3 v3, in vec3 v4, in vec3 p )
{
    #if 1
    // handle ill formed quads
    if( dot( cross( v2-v1, v4-v1 ), cross( v4-v3, v2-v3 )) < 0.0 )
    {
        vec3 tmp = v3;
        v3 = v4;
        v4 = tmp;
    }
    #endif


    vec3 v21 = v2 - v1; vec3 p1 = p - v1;
    vec3 v32 = v3 - v2; vec3 p2 = p - v2;
    vec3 v43 = v4 - v3; vec3 p3 = p - v3;
    vec3 v14 = v1 - v4; vec3 p4 = p - v4;
    vec3 nor = cross( v21, v14 );

    return sqrt( (sign(dot(cross(v21,nor),p1)) + 
                  sign(dot(cross(v32,nor),p2)) + 
                  sign(dot(cross(v43,nor),p3)) + 
                  sign(dot(cross(v14,nor),p4))<3.0) 
                  ?
                  min( min( dot2(v21*clamp(dot(v21,p1)/dot2(v21),0.0,1.0)-p1), 
                            dot2(v32*clamp(dot(v32,p2)/dot2(v32),0.0,1.0)-p2) ), 
                       min( dot2(v43*clamp(dot(v43,p3)/dot2(v43),0.0,1.0)-p3),
                            dot2(v14*clamp(dot(v14,p4)/dot2(v14),0.0,1.0)-p4) ))
                  :
                  dot(nor,p1)*dot(nor,p1)/dot2(nor) );
}

float sdPlane( vec3 p )
{
	return p.y;
}

float sdSphere( vec3 p, float s )
{
    return length(p)-s;
}

float sdBox( vec3 p, vec3 b )
{
    vec3 d = abs(p) - b;
    return min(max(d.x,max(d.y,d.z)),0.0) + length(max(d,0.0));
}

float sdBox( vec3 p, vec3 lo, vec3 hi )
{
    vec3 c = (lo + hi) * .5;
    vec3 b = (hi - lo) * .5;
    return sdBox(p - c, b);
    //vec3 d = abs(p) - b;
    //return min(max(d.x,max(d.y,d.z)),0.0) + length(max(d,0.0));
}

float sdBoxFrame( vec3 p, vec3 b, float e )
{
       p = abs(p  )-b;
  vec3 q = abs(p+e)-e;

  return min(min(
      length(max(vec3(p.x,q.y,q.z),0.0)) + min(max(p.x,max(q.y,q.z)),0.0),
      length(max(vec3(q.x,p.y,q.z),0.0)) + min(max(q.x,max(p.y,q.z)),0.0)),
      length(max(vec3(q.x,q.y,p.z),0.0)) + min(max(q.x,max(q.y,p.z)),0.0));
}

float sdBoxFrame( vec3 p, vec3 lo, vec3 hi, float e )
{
    vec3 c = (lo + hi) * .5;
    vec3 b = (hi - lo) * .5;
    return sdBoxFrame(p - c, b, e);
    //vec3 d = abs(p) - b;
    //return min(max(d.x,max(d.y,d.z)),0.0) + length(max(d,0.0));
}


float sdEllipsoid( in vec3 p, in vec3 r ) // approximated
{
    float k0 = length(p/r);
    float k1 = length(p/(r*r));
    return k0*(k0-1.0)/k1;
}

float sdTorus( vec3 p, vec2 t )
{
    return length( vec2(length(p.xz)-t.x,p.y) )-t.y;
}

float sdCappedTorus(in vec3 p, in vec2 sc, in float ra, in float rb)
{
    p.x = abs(p.x);
    float k = (sc.y*p.x>sc.x*p.y) ? dot(p.xy,sc) : length(p.xy);
    return sqrt( dot(p,p) + ra*ra - 2.0*ra*k ) - rb;
}

float sdHexPrism( vec3 p, vec2 h )
{
    vec3 q = abs(p);

    const vec3 k = vec3(-0.8660254, 0.5, 0.57735);
    p = abs(p);
    p.xy -= 2.0*min(dot(k.xy, p.xy), 0.0)*k.xy;
    vec2 d = vec2(
       length(p.xy - vec2(clamp(p.x, -k.z*h.x, k.z*h.x), h.x))*sign(p.y - h.x),
       p.z-h.y );
    return min(max(d.x,d.y),0.0) + length(max(d,0.0));
}

float sdOctogonPrism( in vec3 p, in float r, float h )
{
  const vec3 k = vec3(-0.9238795325,   // sqrt(2+sqrt(2))/2 
                       0.3826834323,   // sqrt(2-sqrt(2))/2
                       0.4142135623 ); // sqrt(2)-1 
  // reflections
  p = abs(p);
  p.xy -= 2.0*min(dot(vec2( k.x,k.y),p.xy),0.0)*vec2( k.x,k.y);
  p.xy -= 2.0*min(dot(vec2(-k.x,k.y),p.xy),0.0)*vec2(-k.x,k.y);
  // polygon side
  p.xy -= vec2(clamp(p.x, -k.z*r, k.z*r), r);
  vec2 d = vec2( length(p.xy)*sign(p.y), p.z-h );
  return min(max(d.x,d.y),0.0) + length(max(d,0.0));
}

float sdCapsule( vec3 p, vec3 a, vec3 b, float r )
{
	vec3 pa = p-a, ba = b-a;
	float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
	return length( pa - ba*h ) - r;
}

float sdRoundCone( in vec3 p, in float r1, float r2, float h )
{
    vec2 q = vec2( length(p.xz), p.y );

    float b = (r1-r2)/h;
    float a = sqrt(1.0-b*b);
    float k = dot(q,vec2(-b,a));

    if( k < 0.0 ) return length(q) - r1;
    if( k > a*h ) return length(q-vec2(0.0,h)) - r2;

    return dot(q, vec2(a,b) ) - r1;
}

float sdRoundCone(vec3 p, vec3 a, vec3 b, float r1, float r2)
{
    // sampling independent computations (only depend on shape)
    vec3  ba = b - a;
    float l2 = dot(ba,ba);
    float rr = r1 - r2;
    float a2 = l2 - rr*rr;
    float il2 = 1.0/l2;

    // sampling dependant computations
    vec3 pa = p - a;
    float y = dot(pa,ba);
    float z = y - l2;
    float x2 = dot2( pa*l2 - ba*y );
    float y2 = y*y*l2;
    float z2 = z*z*l2;

    // single square root!
    float k = sign(rr)*rr*rr*x2;
    if( sign(z)*a2*z2 > k ) return  sqrt(x2 + z2)        *il2 - r2;
    if( sign(y)*a2*y2 < k ) return  sqrt(x2 + y2)        *il2 - r1;
                            return (sqrt(x2*a2*il2)+y*rr)*il2 - r1;
}

float sdTriPrism( vec3 p, vec2 h )
{
    const float k = sqrt(3.0);
    h.x *= 0.5*k;
    p.xy /= h.x;
    p.x = abs(p.x) - 1.0;
    p.y = p.y + 1.0/k;
    if( p.x+k*p.y>0.0 ) p.xy=vec2(p.x-k*p.y,-k*p.x-p.y)/2.0;
    p.x -= clamp( p.x, -2.0, 0.0 );
    float d1 = length(p.xy)*sign(-p.y)*h.x;
    float d2 = abs(p.z)-h.y;
    return length(max(vec2(d1,d2),0.0)) + min(max(d1,d2), 0.);
}

// vertical
float sdCylinder( vec3 p, vec2 h )
{
    vec2 d = abs(vec2(length(p.xz),p.y)) - h;
    return min(max(d.x,d.y),0.0) + length(max(d,0.0));
}

// arbitrary orientation
float sdCylinder(vec3 p, vec3 a, vec3 b, float r)
{
    vec3 pa = p - a;
    vec3 ba = b - a;
    float baba = dot(ba,ba);
    float paba = dot(pa,ba);

    float x = length(pa*baba-ba*paba) - r*baba;
    float y = abs(paba-baba*0.5)-baba*0.5;
    float x2 = x*x;
    float y2 = y*y*baba;
    float d = (max(x,y)<0.0)?-min(x2,y2):(((x>0.0)?x2:0.0)+((y>0.0)?y2:0.0));
    return sign(d)*sqrt(abs(d))/baba;
}

// vertical
float sdCone( in vec3 p, in vec2 c, float h )
{
    vec2 q = h*vec2(c.x,-c.y)/c.y;
    vec2 w = vec2( length(p.xz), p.y );

	vec2 a = w - q*clamp( dot(w,q)/dot(q,q), 0.0, 1.0 );
    vec2 b = w - q*vec2( clamp( w.x/q.x, 0.0, 1.0 ), 1.0 );
    float k = sign( q.y );
    float d = min(dot( a, a ),dot(b, b));
    float s = max( k*(w.x*q.y-w.y*q.x),k*(w.y-q.y)  );
	return sqrt(d)*sign(s);
}

float sdCappedCone( in vec3 p, in float h, in float r1, in float r2 )
{
    vec2 q = vec2( length(p.xz), p.y );

    vec2 k1 = vec2(r2,h);
    vec2 k2 = vec2(r2-r1,2.0*h);
    vec2 ca = vec2(q.x-min(q.x,(q.y < 0.0)?r1:r2), abs(q.y)-h);
    vec2 cb = q - k1 + k2*clamp( dot(k1-q,k2)/dot2(k2), 0.0, 1.0 );
    float s = (cb.x < 0.0 && ca.y < 0.0) ? -1.0 : 1.0;
    return s*sqrt( min(dot2(ca),dot2(cb)) );
}

float sdCappedCone(vec3 p, vec3 a, vec3 b, float ra, float rb)
{
    float rba  = rb-ra;
    float baba = dot(b-a,b-a);
    float papa = dot(p-a,p-a);
    float paba = dot(p-a,b-a)/baba;

    float x = sqrt( papa - paba*paba*baba );

    float cax = max(0.0,x-((paba<0.5)?ra:rb));
    float cay = abs(paba-0.5)-0.5;

    float k = rba*rba + baba;
    float f = clamp( (rba*(x-ra)+paba*baba)/k, 0.0, 1.0 );

    float cbx = x-ra - f*rba;
    float cby = paba - f;

    float s = (cbx < 0.0 && cay < 0.0) ? -1.0 : 1.0;

    return s*sqrt( min(cax*cax + cay*cay*baba,
                       cbx*cbx + cby*cby*baba) );
}

// c is the sin/cos of the desired cone angle
float sdSolidAngle(vec3 pos, vec2 c, float ra)
{
    vec2 p = vec2( length(pos.xz), pos.y );
    float l = length(p) - ra;
	float m = length(p - c*clamp(dot(p,c),0.0,ra) );
    return max(l,m*sign(c.y*p.x-c.x*p.y));
}

